// Generate a random flags bitmask; API accepts ARES_LIB_INIT_* bits
int flags = (int)(*FUZZ_PARAM(unsigned int));
// Avoid repeated init if the runtime already did so; use global attr to gate
int already = FUZZ_GET_ATTR_INT_GLOBAL("c-ares.libinit");
if (already) { FUZZ_BAIL(); }
int rc = ares_library_init(flags);
if (rc != 0) { FUZZ_BAIL(); }
// Track that library is initialized
FUZZ_SET_ATTR_INT_GLOBAL("c-ares.libinit", 1);

// Provide valid allocator function pointers; NULL is invalid per API
int flags = (int)(*FUZZ_PARAM(unsigned int));
int already = FUZZ_GET_ATTR_INT_GLOBAL("c-ares.libinit");
if (already) { FUZZ_BAIL(); }
int rc = ares_library_init_mem(flags, malloc, free, realloc);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("c-ares.libinit", 1);
// Mark that custom allocators were installed (for potential downstream checks)
FUZZ_SET_ATTR_INT_GLOBAL("c-ares.alloc.custom", 1);

// Query library initialized state; ensure call does not crash
int inited = ares_library_initialized();
// Optionally cross-check with our global tracker when set
int tracked = FUZZ_GET_ATTR_INT_GLOBAL("c-ares.libinit");
// This is a property that should generally hold true if we've set the tracker
if (tracked) { FUZZ_ASSERT(inited != 0, "library should report initialized when tracker is set"); }

// Only call cleanup if we previously initialized the library
int tracked = FUZZ_GET_ATTR_INT_GLOBAL("c-ares.libinit");
if (!tracked) { FUZZ_BAIL(); }
ares_library_cleanup();
// Reset tracker
FUZZ_SET_ATTR_INT_GLOBAL("c-ares.libinit", 0);
FUZZ_SET_ATTR_INT_GLOBAL("c-ares.alloc.custom", 0);

// Randomly decide whether to request numeric version
int want_num = (int)(*FUZZ_PARAM(unsigned int) & 1);
int ver_storage = 0;
int *ver_ptr = want_num ? &ver_storage : NULL;
const char *s = ares_version(ver_ptr);
FUZZ_ASSERT(s != NULL, "ares_version must return a static string");
// If numeric requested, ensure some integer was written
if (want_num) { (void)ver_storage; }

// Ensure options originated from ares_save_options()
if (!FUZZ_GET_ATTR_INT(options, "options.saved")) { FUZZ_BAIL(); }
ares_destroy_options(options);
// Drop pointer; do not return as output

// Validate input channel is an initialized channel
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
// Allocate receiver for options and optmask; caller must later call ares_destroy_options()
struct ares_options *options = (struct ares_options *)malloc(sizeof(*options));
if (!options) { FUZZ_BAIL(); }
memset(options, 0, sizeof(*options));
int optmask = 0;
int rc = ares_save_options((const ares_channel_t *)channel, options, &optmask);
if (rc != 0) {
  free(options);
  FUZZ_BAIL();
}
// Mark the options as requiring destroy via ares_destroy_options()
FUZZ_SET_ATTR_INT(options, "options.saved", 1);
// Validation: options populated and flagged for destruction; channel returned unchanged for continued use.

// Reinitialize the channel; keep it in the pool
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_status_t st = ares_reinit((ares_channel_t *)channel);
(void)st; // Both success and recoverable errors are acceptable; misuse bails via checks above
// Validation: channel remains in pool regardless of ares_reinit return code.

// Destroy the channel; must be valid and have exactly one ref according to our cooperative tracking
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
int refs = FUZZ_GET_ATTR_INT(channel, "channel.refs");
if (refs != 1) { FUZZ_BAIL(); }
ares_destroy((ares_channel_t *)channel);
// Invalidate attributes to prevent reuse
FUZZ_SET_ATTR_INT(channel, "channel.valid", 0);
FUZZ_SET_ATTR_INT(channel, "channel.refs", 0);
// Validation: channel not returned to pool post-destroy to avoid UAF.

// Cancel all pending queries on a valid channel
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_cancel((ares_channel_t *)channel);
// Validation: channel remains valid; pending callbacks (if any) are notified by c-ares.

// Configure IPv4 source address; host byte order
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
unsigned int ip = *FUZZ_PARAM(unsigned int);
ares_set_local_ip4((ares_channel_t *)channel, ip);
// Track that local ip4 was set
FUZZ_SET_ATTR_INT(channel, "local.ipv4.set", 1);
// Validation: channel kept; attribute records configuration action.

// Bind to a specific network interface by name
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
std::string dev = FUZZ_PARAM_STR();
ares_set_local_dev((ares_channel_t *)channel, dev.c_str());
FUZZ_SET_ATTR_STR(channel, "local.dev", dev.c_str());
// Validation: channel kept; attribute records device binding request.

// Register or clear socket creation callback; NULL to clear is acceptable
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_sock_create_callback cb = NULL;
void *user = NULL;
ares_set_socket_callback((ares_channel_t *)channel, cb, user);
FUZZ_SET_ATTR_INT(channel, "cb.socket.create.set", 1);
// Validation: no-op registration; channel retained.

// Register or clear socket configure callback; NULL to clear is acceptable
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_sock_config_callback cb = NULL;
void *user = NULL;
ares_set_socket_configure_callback((ares_channel_t *)channel, cb, user);
FUZZ_SET_ATTR_INT(channel, "cb.socket.config.set", 1);
// Validation: no-op registration; channel retained.

// Register or clear server state callback; NULL to clear is acceptable
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_server_state_callback cb = NULL;
void *user = NULL;
ares_set_server_state_callback((ares_channel_t *)channel, cb, user);
FUZZ_SET_ATTR_INT(channel, "cb.server.state.set", 1);
// Validation: no-op registration; channel retained.

// Register or clear pending write callback; NULL to clear is acceptable
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_pending_write_cb cb = NULL;
void *user = NULL;
ares_set_pending_write_cb((ares_channel_t *)channel, cb, user);
FUZZ_SET_ATTR_INT(channel, "cb.pending.write.set", 1);
// Validation: no-op registration; channel retained.

// Register or clear query enqueue callback; NULL to clear is acceptable
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_query_enqueue_cb cb = NULL;
void *user = NULL;
ares_set_query_enqueue_cb((ares_channel_t *)channel, cb, user);
FUZZ_SET_ATTR_INT(channel, "cb.query.enqueue.set", 1);
// Validation: no-op registration; channel retained.

// Process any pending writes queued by c-ares
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
ares_process_pending_write((ares_channel_t *)channel);
// Validation: safe to call; channel remains valid for further operations.

// Configure the sortlist from a fuzzed string
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
std::string sortstr = FUZZ_PARAM_STR();
int rc = ares_set_sortlist((ares_channel_t *)channel, sortstr.c_str());
(void)rc; // API may return error on malformed sortlist; not a misuse if channel is valid
// Track last sortlist string for potential diagnostics
FUZZ_SET_ATTR_STR(channel, "sortlist.last", sortstr.c_str());
// Validation: channel preserved regardless of return code; attribute records attempt.

// Asynchronously resolve host/service; provide a callback that frees result
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
std::string node = FUZZ_PARAM_STR();
std::string service = FUZZ_PARAM_STR();
// Randomly decide to provide hints or NULL
int provide_hints = (int)(*FUZZ_PARAM(unsigned int) & 1);
struct ares_addrinfo_hints hints;
memset(&hints, 0, sizeof(hints));
if (provide_hints) {
  hints.ai_family = (int)(*FUZZ_PARAM(unsigned int) % 3 == 0 ? AF_UNSPEC : (*FUZZ_PARAM(unsigned int) & 1 ? AF_INET : AF_INET6));
  hints.ai_socktype = (int)(*FUZZ_PARAM(unsigned int) % 3); // may be 0/1/2
  hints.ai_protocol = (int)(*FUZZ_PARAM(unsigned int));
  hints.ai_flags = (int)(*FUZZ_PARAM(unsigned int));
}
ares_addrinfo_callback cb = [](void *arg, int status, int timeouts, struct ares_addrinfo *res) {
  (void)arg; (void)status; (void)timeouts;
  // Free result if provided per API requirement
  if (res) { ares_freeaddrinfo(res); }
};
void *arg = NULL;
ares_getaddrinfo((ares_channel_t *)channel, node.c_str(), service.c_str(), provide_hints ? &hints : NULL, cb, arg);
// To avoid leaving work outstanding in the fuzzer, immediately cancel queued work
ares_cancel((ares_channel_t *)channel);
// Validation: query enqueued and then cancelled; callback tolerant to NULL result; channel remains valid.

// Override socket functions with a minimal vtable; all functions must be defined per API
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
// Provide capture-less lambdas convertible to function pointers
struct ares_socket_functions funcs;
funcs.asocket = [](int, int, int, void *) -> ares_socket_t { return ARES_SOCKET_BAD; };
funcs.aclose = [](ares_socket_t, void *) -> int { return 0; };
funcs.aconnect = [](ares_socket_t, const struct sockaddr *, ares_socklen_t, void *) -> int { return -1; };
funcs.arecvfrom = [](ares_socket_t, void *, size_t, int, struct sockaddr *, ares_socklen_t *, void *) -> ares_ssize_t { return -1; };
funcs.asendv = [](ares_socket_t, const struct iovec *, int, void *) -> ares_ssize_t { return -1; };
void *user = NULL;
ares_set_socket_functions((ares_channel_t *)channel, &funcs, user);
FUZZ_SET_ATTR_INT(channel, "sockfuncs.set", 1);
// Validation: vtable fully populated; channel preserved for subsequent operations.

// Initialize a channel with defaults using the legacy initializer
// Requires library initialized on some platforms; if not initialized, the call may still succeed.
ares_channel_t *tmp = NULL;
int rc = ares_init(&tmp);
if (rc != 0 || tmp == NULL) { FUZZ_BAIL(); }
// Adopt the returned handle into the fuzzer's pool type
ares_channel *channel = (ares_channel *)tmp;
// Track validity and a simple ref marker for ownership in the pool
FUZZ_SET_ATTR_INT(channel, "channel.valid", 1);
FUZZ_SET_ATTR_INT(channel, "channel.refs", 1);
// Validation: channel is non-null on success and marked valid for downstream use.

// Create a channel using no explicit options (options == NULL, optmask == 0)
ares_channel_t *tmp = NULL;
const struct ares_options *opts = NULL;
int optmask = 0;
int rc = ares_init_options(&tmp, opts, optmask);
if (rc != 0 || tmp == NULL) { FUZZ_BAIL(); }
ares_channel *channel = (ares_channel *)tmp;
FUZZ_SET_ATTR_INT(channel, "channel.valid", 1);
FUZZ_SET_ATTR_INT(channel, "channel.refs", 1);
// Validation: channel created successfully and tagged as valid for the pool.

// Duplicate an existing, valid channel
if (!FUZZ_GET_ATTR_INT(src, "channel.valid")) { FUZZ_BAIL(); }
ares_channel_t *tmp = NULL;
int rc = ares_dup(&tmp, (const ares_channel_t *)src);
if (rc != 0 || tmp == NULL) { FUZZ_BAIL(); }
ares_channel *dest = (ares_channel *)tmp;
FUZZ_SET_ATTR_INT(dest, "channel.valid", 1);
FUZZ_SET_ATTR_INT(dest, "channel.refs", 1);
// Validation: duplicated channel is non-null and marked valid; src preserved for further operations.

// Configure IPv6 source address; requires exactly 16 bytes
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
unsigned char buf16[16];
const unsigned char (*arr)[16] = FUZZ_PARAM(unsigned char[16]);
memcpy(buf16, *arr, 16);
ares_set_local_ip6((ares_channel_t *)channel, buf16);
FUZZ_SET_ATTR_INT(channel, "local.ipv6.set", 1);
// Validation: channel kept; attribute records configuration action.

// Override socket functions with extended vtable; provide required callbacks
if (!FUZZ_GET_ATTR_INT(channel, "channel.valid")) { FUZZ_BAIL(); }
struct ares_socket_functions_ex funcs;
memset(&funcs, 0, sizeof(funcs));
funcs.version = 1; // required
funcs.flags = 0;   // no special flags
// Minimal implementations; non-blocking semantics are assumed by caller; returning errors is acceptable
funcs.asocket = [](int, int, int, void *) -> ares_socket_t { return ARES_SOCKET_BAD; };
funcs.aclose = [](ares_socket_t, void *) -> int { return 0; };
funcs.asetsockopt = [](ares_socket_t, ares_socket_opt_t, const void *, ares_socklen_t, void *) -> int { return -1; };
