import random
import ipaddress
from typing import List

# Generates valid DNS resolver sortlist strings as used by ares_set_sortlist.
# The function returns bytes (NUL-terminated not required by fuzzer, but the
# C++ stub will call c_str(), so a Python bytes without NUL is fine). Keep size <= 4096.

PRIVATE_NETS = [
    ipaddress.IPv4Network('10.0.0.0/8'),
    ipaddress.IPv4Network('172.16.0.0/12'),
    ipaddress.IPv4Network('192.168.0.0/16'),
    ipaddress.IPv4Network('100.64.0.0/10'),
]

PUBLIC_NETS = [
    ipaddress.IPv4Network('8.8.8.0/24'),
    ipaddress.IPv4Network('1.1.1.0/24'),
    ipaddress.IPv4Network('9.9.9.0/24'),
    ipaddress.IPv4Network('208.67.222.0/24'),
]

SPECIALS = [
    # Edge cases and interesting masks/prefixes
    ('0.0.0.0/0', None),
    ('127.0.0.0/255.0.0.0', None),
    ('224.0.0.0/240.0.0.0', None),  # multicast range block
    ('255.255.255.255/255.255.255.255', None),
]


def _rand_net(rng: random.Random) -> ipaddress.IPv4Network:
    pool = PRIVATE_NETS + PUBLIC_NETS
    net = rng.choice(pool)
    # Randomize a subnet within the chosen network
    new_prefix = rng.randint(net.prefixlen, 30)
    return ipaddress.IPv4Network((int(net.network_address), new_prefix))


def _fmt_cidr(net: ipaddress.IPv4Network) -> str:
    return f"{net.network_address}/{net.prefixlen}"


def _fmt_mask(net: ipaddress.IPv4Network) -> str:
    return f"{net.network_address}/{net.netmask}"


def _random_entry(rng: random.Random) -> str:
    # Choose between CIDR, netmask, host-only, or a special literal
    choice = rng.random()
    if choice < 0.15:
        s, _ = rng.choice(SPECIALS)
        return s
    net = _rand_net(rng)
    t = rng.random()
    if t < 0.45:
        return _fmt_cidr(net)
    elif t < 0.9:
        return _fmt_mask(net)
    else:
        # Host-only form (implies /32)
        host = str(net.network_address)
        return host


def _shuffle_spaces(entries: List[str], rng: random.Random) -> str:
    # Join entries with a mix of single/multiple spaces and occasional tabs
    parts = []
    for i, e in enumerate(entries):
        parts.append(e)
        if i != len(entries) - 1:
            sep_kind = rng.randint(0, 4)
            if sep_kind == 0:
                parts.append(' ')
            elif sep_kind == 1:
                parts.append('  ')
            elif sep_kind == 2:
                parts.append('\t')
            elif sep_kind == 3:
                parts.append('   ')
            else:
                parts.append(' ')  # default single space
    return ''.join(parts)


def _maybe_leading_trailing_ws(s: str, rng: random.Random) -> str:
    if rng.random() < 0.5:
        s = (' ' * rng.randint(0, 2)) + s
    if rng.random() < 0.5:
        s = s + (' ' * rng.randint(0, 2))
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide how many entries to include (1..8 typical, occasionally more)
    n = rng.choices([1, 2, 3, 4, 5, 6, 7, 8, 12, 16], weights=[8, 10, 12, 12, 10, 8, 6, 5, 4, 3], k=1)[0]

    entries: List[str] = []
    for _ in range(n):
        entry = _random_entry(rng)
        entries.append(entry)

    # Occasionally duplicate or reorder to simulate realistic admin strings
    if rng.random() < 0.3 and len(entries) >= 2:
        i = rng.randrange(len(entries))
        entries.insert(rng.randrange(len(entries) + 1), entries[i])
    if rng.random() < 0.5:
        rng.shuffle(entries)

    s = _shuffle_spaces(entries, rng)
    s = _maybe_leading_trailing_ws(s, rng)

    # Ensure length bounds
    if len(s) > 4096:
        s = s[:4096]

    return s.encode('ascii')

import random
import struct
import ipaddress
from typing import List, Tuple

# This generator builds valid DNS wire-format messages suitable for:
# - ares_send (as a raw query)
# - ares_expand_name / ares_expand_string (by embedding valid names/strings at various offsets)
# - ares_parse_*_reply functions for A/AAAA/NS/SRV/MX/TXT/NAPTR/SOA/URI/CAA/PTR
# It constructs a header, a single QD, and between 0..N valid RRs of diverse types, with
# correct name compression and RDLENGTHs. The overall packet stays <= 4096 bytes.

# DNS constants
CLASS_IN = 1
TYPE_A = 1
TYPE_NS = 2
TYPE_CNAME = 5
TYPE_SOA = 6
TYPE_PTR = 12
TYPE_MX = 15
TYPE_TXT = 16
TYPE_AAAA = 28
TYPE_SRV = 33
TYPE_NAPTR = 35
TYPE_URI = 256  # per RFC 7553 in some libs
TYPE_CAA = 257

MAX_PACKET = 4096

# Helper to encode a domain name with optional compression using an offset table
class NameCompressor:
    def __init__(self):
        self.offsets = {}

    def encode_name(self, name: str, cur_offset: int, out: bytearray) -> bytes:
        # Normalize: ensure root-terminated
        if name == "." or name == "":
            return b"\x00"
        labels = name.rstrip('.').split('.')
        encoded = bytearray()
        # Try to find longest suffix present to compress
        for i in range(len(labels)):
            suffix = '.'.join(labels[i:])
            if suffix in self.offsets:
                # emit remaining labels before pointer
                for lab in labels[:i]:
                    lb = lab.encode('utf-8', 'ignore')[:63]
                    encoded.append(len(lb))
                    encoded += lb
                ptr = self.offsets[suffix]
                encoded += struct.pack('!H', 0xC000 | ptr)
                return bytes(encoded)
        # No compression: emit all labels and root
        for lab in labels:
            lb = lab.encode('utf-8', 'ignore')[:63]
            encoded.append(len(lb))
            encoded += lb
        encoded.append(0)
        # Register all suffixes with their absolute offsets
        # The encoded name will be placed at cur_offset in the final buffer
        tmp = 0
        lbls = labels
        for i in range(len(lbls)):
            suffix = '.'.join(lbls[i:])
            if suffix not in self.offsets:
                self.offsets[suffix] = cur_offset + tmp
            # advance tmp by len(label)+1
            tmp += len(lbls[i]) + 1
        return bytes(encoded)

# Simple builders for RR RDATA

def rdata_a() -> bytes:
    ip = ipaddress.IPv4Address(random.randrange(0, 2**32))
    return ip.packed

def rdata_aaaa() -> bytes:
    ip = ipaddress.IPv6Address(random.randrange(0, 2**128))
    return ip.packed

def rdata_ns(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    host = rand_hostname()
    return name_comp.encode_name(host, cur_off, out)

def rdata_cname(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    host = rand_hostname()
    return name_comp.encode_name(host, cur_off, out)

def rdata_ptr(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    host = rand_hostname()
    return name_comp.encode_name(host, cur_off, out)

def rdata_mx(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    pref = random.randrange(0, 65536)
    exch = rand_hostname()
    enc = struct.pack('!H', pref)
    enc += name_comp.encode_name(exch, cur_off + len(enc), out)
    return enc

def rdata_txt() -> bytes:
    # Build one or more <len><data> chunks
    parts: List[bytes] = []
    n = random.randint(1, 3)
    for _ in range(n):
        s = rand_txt()
        b = s.encode('utf-8')[:255]
        parts.append(bytes([len(b)]) + b)
    return b''.join(parts)

def rdata_soa(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    mname = rand_hostname()
    rname = rand_hostname()
    seq = [
        name_comp.encode_name(mname, cur_off, out),
    ]
    cur = cur_off + len(seq[-1])
    seq.append(name_comp.encode_name(rname, cur, out))
    cur += len(seq[-1])
    # serial, refresh, retry, expire, minimum
    ints = [random.randrange(0, 2**32) for _ in range(5)]
    enc_ints = b''.join(struct.pack('!I', x) for x in ints)
    return b''.join(seq) + enc_ints

def rdata_srv(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    prio = random.randrange(0, 65536)
    weight = random.randrange(0, 65536)
    port = random.randrange(1, 65536)
    target = rand_hostname()
    head = struct.pack('!HHH', prio, weight, port)
    name_bytes = name_comp.encode_name(target, cur_off + len(head), out)
    return head + name_bytes

def rdata_naptr(name_comp: NameCompressor, cur_off: int, out: bytearray) -> bytes:
    order = random.randrange(0, 65536)
    pref = random.randrange(0, 65536)
    flags = rand_charstr(maxlen=16)
    services = rand_charstr(maxlen=32)
    regexp = rand_charstr(maxlen=32)
    repl = name_comp.encode_name(rand_hostname(), cur_off + 4 + 1 + len(flags) + 1 + len(services) + 1 + len(regexp), out)
    enc = struct.pack('!HH', order, pref)
    enc += bytes([len(flags)]) + flags
    enc += bytes([len(services)]) + services
    enc += bytes([len(regexp)]) + regexp
    enc += repl
    return enc

def rdata_uri() -> bytes:
    prio = random.randrange(0, 65536)
    weight = random.randrange(0, 65536)
    target = random.choice([
        "https://example.com/",
        "sip:alice@example.com",
        "https://svc.example.org/path",
        "ftp://files.example.net/pub"
    ]).encode('utf-8')
    return struct.pack('!HH', prio, weight) + bytes([len(target)]) + target

def rdata_caa() -> bytes:
    critical = random.randint(0, 1)
    tag = random.choice([b'issue', b'issuewild', b'iodef', b'contactemail', b'contactphone'])
    val = random.choice([
        b'letsencrypt.org',
        b'comodoca.com',
        b'mailto:admin@example.com',
        b'tel:+15551234567'
    ])
    r = bytes([critical & 0x01]) + bytes([len(tag)]) + tag + bytes([len(val)]) + val
    return r

# Random helpers

def rand_label(minlen=1, maxlen=10) -> str:
    n = random.randint(minlen, maxlen)
    chars = 'abcdefghijklmnopqrstuvwxyz0123456789-'
    s = ''.join(random.choice(chars) for _ in range(n))
    s = s.strip('-')
    if not s:
        s = 'a'
    return s[:63]

def rand_hostname() -> str:
    depth = random.randint(1, 4)
    labels = [rand_label() for _ in range(depth)]
    # Ensure TLD plausible
    tld = random.choice(['com', 'net', 'org', 'io', 'arpa', 'example'])
    labels[-1] = tld
    return '.'.join(labels)

def rand_txt() -> str:
    # Printable TXT
    chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 _-.:/@'
    n = random.randint(1, 200)
    return ''.join(random.choice(chars) for _ in range(n))

def rand_charstr(maxlen=32) -> bytes:
    chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._'
    n = random.randint(0, min(20, maxlen))
    return ''.join(random.choice(chars) for _ in range(n)).encode('utf-8')

# RR builder descriptor
class RRSpec:
    def __init__(self, rtype: int, builder):
        self.rtype = rtype
        self.builder = builder


def build_dns_packet() -> bytes:
