        nonlocal ancount, out
        # Name
        name_bytes = name_comp.encode_name(name, len(out), out)
        rclass = CLASS_IN
        # Reserve space to compute RDLENGTH correctly
        rdata_start = len(out) + len(name_bytes) + 10  # TYPE(2)+CLASS(2)+TTL(4)+RDLEN(2)
        # Header for RR (name will be appended first)
        out += name_bytes
        out += struct.pack('!HHI', rrtype, rclass, ttl)
        # Placeholder RDLENGTH
        rdl_pos = len(out)
        out += b'\x00\x00'
        # RDATA
        rdata = rr_builder(rrtype, len(out), out)
        out += rdata
        # Patch RDLENGTH
        rdlen = len(out) - (rdl_pos + 2)
        out[rdl_pos:rdl_pos+2] = struct.pack('!H', rdlen)
        ancount += 1

    def rr_builder(rrtype: int, cur_off: int, outbuf: bytearray) -> bytes:
        if rrtype == TYPE_A:
            return rdata_a()
        if rrtype == TYPE_AAAA:
            return rdata_aaaa()
        if rrtype == TYPE_NS:
            return rdata_ns(name_comp, cur_off, outbuf)
        if rrtype == TYPE_CNAME:
            return rdata_cname(name_comp, cur_off, outbuf)
        if rrtype == TYPE_PTR:
            return rdata_ptr(name_comp, cur_off, outbuf)
        if rrtype == TYPE_MX:
            return rdata_mx(name_comp, cur_off, outbuf)
        if rrtype == TYPE_TXT:
            return rdata_txt()
        if rrtype == TYPE_SOA:
            return rdata_soa(name_comp, cur_off, outbuf)
        if rrtype == TYPE_SRV:
            return rdata_srv(name_comp, cur_off, outbuf)
        if rrtype == TYPE_NAPTR:
            return rdata_naptr(name_comp, cur_off, outbuf)
        if rrtype == TYPE_URI:
            return rdata_uri()
        if rrtype == TYPE_CAA:
            return rdata_caa()
        # Fallback empty
        return b''

    # Primary RR uses question name or a related name depending on type
    base_name = qname
    # For CNAME flows, point to another name sometimes
    for spec in rr_specs:
        name_for_rr = base_name
        ttl = random.randint(30, 86400)
        # For CNAME, sometimes change owner to first label + qname to mix compression
        if spec.rtype == TYPE_CNAME and random.random() < 0.5:
            name_for_rr = rand_label() + '.' + base_name
        append_rr(name_for_rr, spec.rtype, ttl)
        if len(out) > MAX_PACKET - 64:
            break

    # Update counts (ANCOUNT), no NS/AR for simplicity
    # Rewrite header with updated counts
    # Header was first 12 bytes
    # QDCOUNT fixed at 1, ANCOUNT=ancount
    out[0:12] = struct.pack('!HHHHHH', qid, flags, 1, ancount, 0, 0)

    # Ensure maximum size
    return bytes(out[:MAX_PACKET])


def generate(seed: int) -> bytes:
    random.seed(seed)
    pkt = build_dns_packet()
    # Guarantee non-empty to satisfy parsers expecting some content
    if not pkt:
        return b"\x00" * 12
    return pkt
